using System.Globalization;using System.IO;using System.Text.Json;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Media;using LifeOS.Core.ConfigurationReadiness;using LifeOS.Core.Forms;using LifeOS.Core.ProviderAdapters;using LifeOS.Core.ProviderConsent;using LifeOS.Shared.ProviderConsent;using LifeOS.Shared.Storage;
namespace LifeOS.Desktop;
public sealed class ProviderConsentWorkspaceView:UserControl
{
 private readonly bool _demo;private List<ProviderConsentRecord>_records=[];private IReadOnlyList<FormFieldIssue>_issues=[];private UserFacingProblem?_problem;private string?_notice;private string _name="",_owner="",_purpose="",_expiry="",_notes="";private ProviderFamily _family;private ConfigurationEnvironment _environment;private ProviderCapability _capabilities;
 public ProviderConsentWorkspaceView(bool demo){_demo=demo;Background=B("#0C1220");Foreground=Brushes.White;FontFamily=new("Segoe UI");try{_records=ProviderConsentStorage.Load();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException){_problem=UserFacingProblemFactory.FromException(ex,"load provider consent");}Render();}
 private void Render(){StackPanel root=new(){Margin=new(24)};root.Children.Add(T(_demo?"PORTFOLIO DEMO • ISOLATED":"ORDINARY MODE • NO PROVIDER ACCESS",11,"#AFA4FF",FontWeights.SemiBold));root.Children.Add(T("Provider Consent & Permission Profiles",30,"#FFFFFF",FontWeights.Bold));root.Children.Add(T("Define purpose-bound capability consent with explicit approval, pause and revocation. Consent never enables credentials, OAuth, endpoints or provider access in this configuration-free release.",14,"#B8C5D8"));if(_notice!=null)root.Children.Add(T(_notice,12,"#83D4B3",FontWeights.SemiBold));if(_problem!=null)root.Children.Add(Problem(_problem));WrapPanel m=new(){Margin=new(0,16,0,8)};m.Children.Add(Metric("Profiles",_records.Count.ToString(),"Local metadata"));m.Children.Add(Metric("Approved",_records.Count(x=>x.State==ProviderConsentState.Approved).ToString(),"Explicit state"));m.Children.Add(Metric("Paused / revoked",_records.Count(x=>x.State is ProviderConsentState.Paused or ProviderConsentState.Revoked).ToString(),"Owner control"));m.Children.Add(Metric("Provider access","0","Hard boundary"));root.Children.Add(m);root.Children.Add(Capture());root.Children.Add(H("Permission profiles",21,new(0,20,0,6)));if(_records.Count==0)root.Children.Add(Card("No consent profiles yet","Ordinary mode starts empty. Proposed consent is local metadata and grants no provider access.","#151F30"));else foreach(var r in _records)root.Children.Add(Record(r));LocalStoreHealth health=ProviderConsentStorage.Inspect();root.Children.Add(H("Consent boundary",21,new(0,20,0,6)));root.Children.Add(Card("Versioned provider-consent store",$"State: {health.State}. Approval records intent only; credentialed provider access remains unavailable until separately configured and tested.","#152437"));Content=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=root};}
 private UIElement Capture(){StackPanel p=new();p.Children.Add(H("Propose a permission profile",20));WrapPanel row=new();row.Children.Add(Input("Profile name *","consent-name","ProviderConsent.Name",_name,v=>_name=v,480));row.Children.Add(Input("Owner *","consent-owner","ProviderConsent.Owner",_owner,v=>_owner=v,480));p.Children.Add(row);WrapPanel choices=new();choices.Children.Add(Choice("Provider family","ProviderConsent.Family",Enum.GetValues<ProviderFamily>(),_family,v=>_family=v,480));choices.Children.Add(Choice("Environment","ProviderConsent.Environment",Enum.GetValues<ConfigurationEnvironment>(),_environment,v=>_environment=v,480));p.Children.Add(choices);p.Children.Add(H("Requested capabilities *",14,new(0,12,0,2)));WrapPanel caps=new();foreach(var x in Enum.GetValues<ProviderCapability>().Where(x=>x!=ProviderCapability.None)){ProviderCapability flag=x;CheckBox box=new(){Content=x.ToString(),Foreground=Brushes.White,Margin=new(0,4,18,4),IsChecked=_capabilities.HasFlag(x)};AutomationProperties.SetAutomationId(box,$"ProviderConsent.Capability.{x}");box.Checked+=(_,_)=>_capabilities|=flag;box.Unchecked+=(_,_)=>_capabilities&=~flag;caps.Children.Add(box);}p.Children.Add(caps);string ce=string.Join(" ",_issues.Where(i=>i.FieldId=="consent-capabilities").Select(i=>i.Message));if(ce.Length>0)p.Children.Add(T(ce,11,"#FF7788",FontWeights.SemiBold));p.Children.Add(Input("Purpose *","consent-purpose","ProviderConsent.Purpose",_purpose,v=>_purpose=v,970));p.Children.Add(Input("Expiry (optional, yyyy-MM-dd)","consent-expiry","ProviderConsent.Expiry",_expiry,v=>_expiry=v,480));p.Children.Add(Input("Notes","consent-notes","ProviderConsent.Notes",_notes,v=>_notes=v,970));Button add=Btn("Propose permission profile","ProviderConsent.Add",false);add.Click+=(_,_)=>Add();p.Children.Add(add);return Panel(p,new(0,14,0,0));}
 private UIElement Record(ProviderConsentRecord r){StackPanel p=new();DockPanel h=new();TextBlock s=T(r.State.ToString().ToUpperInvariant(),11,"#AFA4FF",FontWeights.SemiBold);DockPanel.SetDock(s,Dock.Right);h.Children.Add(s);h.Children.Add(H(r.ProfileName,18));p.Children.Add(h);p.Children.Add(T($"{r.Family} • {r.Environment} • owner: {r.Owner}",12,"#A9B6CA"));p.Children.Add(T($"Capabilities: {string.Join(" • ",Flags(r.Capabilities))}",13,"#E7ECF4",FontWeights.SemiBold));p.Children.Add(T($"Purpose: {r.Purpose}",12,"#C2CDDC"));p.Children.Add(T($"Expiry: {(r.ExpiresOn?.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)??"not set")}",12,"#C2CDDC"));p.Children.Add(T("Provider access: DISABLED",12,"#FFB3BD",FontWeights.SemiBold));WrapPanel a=new();foreach(var x in Actions(r.State)){ProviderConsentState state=x;Button b=Btn(state==ProviderConsentState.Approved?"Approve":state==ProviderConsentState.Paused?"Pause":state==ProviderConsentState.Revoked?"Revoke":"Repropose",$"ProviderConsent.State.{state}.{r.Id:N}",true);b.Click+=(_,_)=>Change(r,state);a.Children.Add(b);}p.Children.Add(a);return Panel(p,new(0,8,0,0));}
 private void Add(){DateOnly?expiry=null;if(_expiry.Trim().Length>0){if(!DateOnly.TryParseExact(_expiry.Trim(),"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out DateOnly parsed)){_issues=[new("consent-expiry","expiry","Use yyyy-MM-dd.")];_problem=new("provider-consent-validation-failed","Review the consent fields","No profile was added because the expiry is invalid.","Use yyyy-MM-dd or leave expiry empty.",true);Render();return;}expiry=parsed;}DateOnly today=DateOnly.FromDateTime(DateTime.Today);ProviderConsentDraft d=new(_name,_family,_owner,_environment,_capabilities,_purpose,expiry,_notes);FormValidationResult v=ProviderConsentService.Validate(d,today);_issues=v.Issues;if(!v.IsValid){_problem=new("provider-consent-validation-failed","Review the consent fields","No profile was added because the fields are invalid or appear to contain a credential.","Remove credential values and correct the highlighted fields.",true);Render();return;}try{var r=ProviderConsentService.Create(d,today,DateTimeOffset.UtcNow);var c=_records.Append(r).ToList();ProviderConsentStorage.Save(c);_records=c;_name=_owner=_purpose=_expiry=_notes="";_capabilities=ProviderCapability.None;_issues=[];_problem=null;_notice="Proposed local consent metadata without enabling provider access.";Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException){_problem=UserFacingProblemFactory.FromException(ex,"save provider consent");Render();}}
 private void Change(ProviderConsentRecord r,ProviderConsentState state){try{DateOnly today=DateOnly.FromDateTime(DateTime.Today);var x=ProviderConsentService.SetState(r,state,today,DateTimeOffset.UtcNow);var c=_records.Select(v=>v.Id==r.Id?x:v).ToList();ProviderConsentStorage.Save(c);_records=c;_notice=$"{r.ProfileName} is now {state.ToString().ToLowerInvariant()}; provider access remains disabled.";_problem=null;Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException or InvalidOperationException){_problem=UserFacingProblemFactory.FromException(ex,"change provider consent");Render();}}
 private UIElement Input(string l,string f,string id,string val,Action<string>ch,double w){StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));TextBox x=new(){Text=val,MinHeight=38,Background=B("#101827"),Foreground=Brushes.White,BorderBrush=B("#3A4B66"),Padding=new(10,7,10,7)};AutomationProperties.SetAutomationId(x,id);x.TextChanged+=(_,_)=>ch(x.Text);p.Children.Add(x);string e=string.Join(" ",_issues.Where(i=>i.FieldId==f).Select(i=>i.Message));if(e.Length>0)p.Children.Add(T(e,11,"#FF7788",FontWeights.SemiBold));return p;}private static UIElement Choice<TValue>(string l,string id,IReadOnlyList<TValue>vals,TValue sel,Action<TValue>ch,double w)where TValue:struct{StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));ComboBox x=new(){ItemsSource=vals,SelectedItem=sel,MinHeight=38};AutomationProperties.SetAutomationId(x,id);x.SelectionChanged+=(_,_)=>{if(x.SelectedItem is TValue v)ch(v);};p.Children.Add(x);return p;}private static List<string>Flags(ProviderCapability c)=>Enum.GetValues<ProviderCapability>().Where(x=>x!=ProviderCapability.None&&c.HasFlag(x)).Select(x=>x.ToString()).ToList();private static IEnumerable<ProviderConsentState>Actions(ProviderConsentState s)=>s switch{ProviderConsentState.Proposed=>[ProviderConsentState.Approved,ProviderConsentState.Revoked],ProviderConsentState.Approved=>[ProviderConsentState.Paused,ProviderConsentState.Revoked],ProviderConsentState.Paused=>[ProviderConsentState.Approved,ProviderConsentState.Revoked],ProviderConsentState.Revoked=>[ProviderConsentState.Proposed],_=>[ProviderConsentState.Proposed]};
 private static Border Problem(UserFacingProblem x){StackPanel p=new();p.Children.Add(H($"{x.Title} ({x.Code})",16));p.Children.Add(T(x.Detail,12,"#E1E7F0"));p.Children.Add(T($"Next: {x.RecoveryAction}",12,"#C5AECF"));return new(){Background=B("#251925"),BorderBrush=B("#C95F75"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(15),Margin=new(0,12,0,0),Child=p};}private static Button Btn(string l,string id,bool s){Button b=new(){Content=l,Background=B(s?"#25334A":"#315E91"),Foreground=Brushes.White,Padding=new(14,7,14,7),Margin=new(0,8,8,0)};AutomationProperties.SetAutomationId(b,id);return b;}private static Border Metric(string l,string v,string d){StackPanel p=new();p.Children.Add(T(l,11,"#9EACC0"));p.Children.Add(T(v,22,"#FFFFFF",FontWeights.SemiBold));p.Children.Add(T(d,11,"#9EACC0"));return new(){Width=230,MinHeight=100,Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(14),Margin=new(0,0,10,10),Child=p};}private static Border Card(string h,string t,string bg){StackPanel p=new();p.Children.Add(H(h,16));p.Children.Add(T(t,12,"#C2CDDC"));return new(){Background=B(bg),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=new(0,8,0,0),Child=p};}private static Border Panel(UIElement x,Thickness m)=>new(){Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=m,Child=x};private static TextBlock H(string t,double s,Thickness?m=null)=>new(){Text=t,FontSize=s,FontWeight=FontWeights.SemiBold,Foreground=Brushes.White,TextWrapping=TextWrapping.Wrap,Margin=m??new(0,0,0,4)};private static TextBlock T(string t,double s,string c,FontWeight?w=null)=>new(){Text=t,FontSize=s,FontWeight=w??FontWeights.Normal,Foreground=B(c),TextWrapping=TextWrapping.Wrap,Margin=new(0,3,0,0)};private static SolidColorBrush B(string v)=>new((Color)ColorConverter.ConvertFromString(v));
}
